// Remove only the original placeholder flashcard whose two sides are Teste 1 / Teste 2.
function removeOriginalTestCard(){
 const norm=v=>String(v||'').replace(/<[^>]*>/g,' ').replace(/&nbsp;/gi,' ').replace(/\s+/g,' ').trim().toLocaleLowerCase('pt-BR').replace(/[.!?]+$/,'');
 const before=(db.cards||[]).length;
 db.cards=(db.cards||[]).filter(c=>{
  const a=norm(c.front),b=norm(c.back);
  return !((a==='teste 1'&&b==='teste 2')||(a==='teste 2'&&b==='teste 1'));
 });
 return before-db.cards.length;
}
