function flashmedApplyPermanentTitleDeletions(target){if(!target)return false;const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toLocaleLowerCase('pt-BR');const matches=x=>/^fazer\s+duolingo\b/.test(norm(x?.title));target.deletedWeeklyTaskTitles=Array.isArray(target.deletedWeeklyTaskTitles)?target.deletedWeeklyTaskTitles:[];if(!target.deletedWeeklyTaskTitles.includes('fazer duolingo'))target.deletedWeeklyTaskTitles.push('fazer duolingo');const p=target.studyPlan||(target.studyPlan={});const before=(p.weeklyTasks||[]).length+(p.weekSchedule||[]).length+(target.agendaEvents||[]).length;p.weeklyTasks=(p.weeklyTasks||[]).filter(x=>!matches(x));p.weekSchedule=(p.weekSchedule||[]).filter(x=>!matches(x));target.agendaEvents=(target.agendaEvents||[]).filter(x=>!matches(x));return before!==p.weeklyTasks.length+p.weekSchedule.length+target.agendaEvents.length}
