function plannerCategoryFromColor(color){const map={'#fff0a6':'viagem','#dce9ff':'viagem','#f7e5c9':'casa','#d9f0df':'atividade','#f3dff0':'autocuidado','#c7e8b5':'outros','#e7def2':'outros'};return map[String(color||'').toLowerCase()]||'outros'}
function plannerDeduplicateEvents(events){
 const seen=new Set();return events.filter(e=>{const original=String(e.title||'').toLocaleLowerCase('pt-BR').trim();const isGyn=/^(aula de ginecologia|seminário de ginecologia)$/.test(original);const title=isGyn?'ginecologia':(original==='aula de obstetrícia'||original==='seminário de obstetrícia')?'obstetrícia':original;const key=String(e.date||'')+'|'+title;if(seen.has(key))return false;seen.add(key);return true}).map(e=>{const title=String(e.title||'').toLocaleLowerCase('pt-BR').trim();if(title==='aula de obstetrícia')return {...e,title:'Seminário de Obstetrícia'};if(title==='seminário de ginecologia')return {...e,title:'Aula de Ginecologia'};return e})
}
function plannerWeeklyScheduleHtml(items){
 flashmedApplyPermanentTitleDeletions(db);
 if(!plannerWeekManuallyNavigated)plannerWeekOffset=plannerDefaultWeekOffset();
 const today=new Date();today.setHours(12,0,0,0);const monday=new Date(today);monday.setDate(today.getDate()-((today.getDay()+6)%7)+plannerWeekOffset*7);const sunday=new Date(monday);sunday.setDate(monday.getDate()+6);
 const startKey=agendaDateKey(monday),endKey=agendaDateKey(sunday),allItems=(items||[]).filter(x=>!/^fazer\s+duolingo\b/.test(String(x?.title||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toLocaleLowerCase('pt-BR'))),days=[];
 for(let i=0;i<7;i++){const d=new Date(monday);d.setDate(monday.getDate()+i);const key=agendaDateKey(d);days.push({d,key,tasks:allItems.filter(x=>x.date===key),events:plannerDeduplicateEvents(agendaEvents().filter(e=>e&&e.date===key&&!e.studyTaskId)).sort((x,y)=>(x.time||'').localeCompare(y.time||''))})}
 if(!days.some(x=>x.key===plannerDayKey))plannerDayKey=startKey;
 const activeDay=days.find(x=>x.key===plannerDayKey)||days[0];
 function eventHtml(e){const fixed=plannerEventIsFixed(e),cls=(fixed?'plannerFixedEvent':'plannerOtherEvent')+(e.priority==='alta'?' priority-high':e.priority==='baixa'?' priority-low':' priority-normal'),color=fixed?'#e7def2':plannerCategoryColor(e.taskCategory||plannerCategoryFromColor(e.color)),key='event:'+String(e.id),date=String(e.date||'');return '<div class="plannerSlotItem '+cls+(e.done?' plannerEventDone':'')+'" draggable="true" data-schedule-key="'+esc(key)+'" data-schedule-date="'+esc(date)+'" ondragstart="plannerScheduleDragStart(event)" ondragover="plannerScheduleDragOver(event)" ondrop="plannerScheduleDrop(event)" ondragend="plannerScheduleDragEnd(event)" style="background:'+color+';border-left-color:'+(fixed?'#8b7e9c':color)+'"><span class="plannerDragGrip" aria-hidden="true" title="Arraste para reorganizar">⠿</span><label class="plannerAgendaEventTitle"><input type="checkbox" '+(e.done?'checked':'')+' onchange="plannerToggleAgendaEvent('+JSON.stringify(String(e.id)).replace(/"/g,'&quot;')+',this.checked)"><span class="'+(e.done?'isDone':'')+'">'+esc(e.title)+'</span></label><div class="plannerSlotTools"><button type="button" title="Editar compromisso" aria-label="Editar compromisso" onclick="plannerEditFixedEvent('+JSON.stringify(String(e.id)).replace(/"/g,'&quot;')+')">✎</button><button type="button" class="plannerDeleteEvent" title="Excluir compromisso" aria-label="Excluir compromisso" onclick="plannerDeleteAgendaEvent('+JSON.stringify(String(e.id)).replace(/"/g,'&quot;')+')">×</button></div></div>'}

 function taskHtml(t){const sourceTask=(db.studyPlan?.weeklyTasks||[]).find(x=>String(x.id)===String(t.taskId||t.id)),priority=sourceTask?.priority||t.priority||'normal',category=t.taskCategory||sourceTask?.taskCategory||plannerCategoryFromColor(t.color),color=plannerCategoryColor(category),key='task:'+String(t.id),date=String(t.date||'');return '<div class="plannerSlotItem plannerStudyItem priority-'+(priority==='alta'?'high':priority==='baixa'?'low':'normal')+'" draggable="true" data-schedule-key="'+esc(key)+'" data-schedule-date="'+esc(date)+'" ondragstart="plannerScheduleDragStart(event)" ondragover="plannerScheduleDragOver(event)" ondrop="plannerScheduleDrop(event)" ondragend="plannerScheduleDragEnd(event)" style="background:'+color+';border-left-color:'+color+'"><span class="plannerDragGrip" aria-hidden="true" title="Arraste para reorganizar">⠿</span><label><input type="checkbox" '+(t.done?'checked':'')+' onchange="toggleWeeklyTask('+JSON.stringify(t.id).replace(/"/g,'&quot;')+',this.checked)"><span class="plannerTaskTitle '+(t.done?'isDone':'')+'">'+esc(t.title)+'</span></label><div class="plannerSlotTools"><button type="button" title="Editar tarefa" aria-label="Editar tarefa" onclick="plannerEditStudyTask('+JSON.stringify(t.id).replace(/"/g,'&quot;')+')">✎</button><button type="button" class="plannerDeleteEvent" title="Excluir tarefa" aria-label="Excluir tarefa" onclick="plannerDeleteNaturalTask('+JSON.stringify(t.taskId||t.id).replace(/"/g,'&quot;')+')">×</button></div></div>'}

 const allDays=plannerScheduleMode==='day'?[activeDay]:days;
 const dayHead=allDays.map(day=>'<th class="plannerTimeDayHead '+(day.key===agendaDateKey(today)?'today':'')+'"><span>'+esc(day.d.toLocaleDateString('pt-BR',{weekday:'short'}))+'</span><b>'+day.d.getDate()+'</b></th>').join('');
 const body=allDays.map(day=>{const entries=[...day.events.map(e=>({key:'event:'+String(e.id),time:e.time||'',html:eventHtml(e)})),...day.tasks.map(t=>({key:'task:'+String(t.id),time:t.time||t.startTime||'',html:taskHtml(t)}))];const savedOrder=((db.studyPlan||{}).weeklyCardOrder||{})[day.key]||[];entries.sort((a,b)=>{const ia=savedOrder.indexOf(a.key),ib=savedOrder.indexOf(b.key);if(ia>=0&&ib>=0)return ia-ib;if(ia>=0)return -1;if(ib>=0)return 1;const rank=x=>!x?3:Number(x.slice(0,2))<12?0:Number(x.slice(0,2))<18?1:2;return rank(a.time)-rank(b.time)||(a.time||'').localeCompare(b.time||'')});return '<td><div class="plannerDayItems" data-schedule-day="'+esc(day.key)+'">'+entries.map(x=>x.html).join('')+(!entries.length?'<span class="plannerEmptyDay">—</span>':'')+'</div></td>'}).join('');
 const label=agendaFormatDate(startKey,{day:'2-digit',month:'short'})+' – '+agendaFormatDate(endKey,{day:'2-digit',month:'short',year:'numeric'});
 return '<div class="plannerWeekNav"><button class="btn ghost" '+(plannerWeekOffset===0?'disabled':'')+' onclick="plannerMoveWeek(-1)">← Anterior</button><b>'+esc(label)+'</b><button class="btn ghost" onclick="plannerMoveWeek(1)">Próxima →</button></div><div class="plannerScheduleControls"><div class="plannerScheduleToggle"><button type="button" class="'+(plannerScheduleMode==='day'?'active':'')+'" onclick="plannerSetScheduleMode(\'day\')">Um dia</button><button type="button" class="'+(plannerScheduleMode==='week'?'active':'')+'" onclick="plannerSetScheduleMode(\'week\')">Semana inteira</button></div></div><div class="plannerWeeklyGridWrap"><table class="plannerWeeklyGrid plannerCompactGrid"><thead><tr><th class="plannerTimeLabel">Dia</th>'+dayHead+'</tr></thead><tbody><tr><th class="plannerTimeLabel">Agenda</th>'+body+'</tr></tbody></table></div>';
}
let plannerDraggingScheduleCard=null;
function plannerScheduleDragStart(ev){const card=ev.currentTarget;if(!card||!card.dataset.scheduleKey)return;plannerDraggingScheduleCard=card;ev.dataTransfer.effectAllowed='move';ev.dataTransfer.setData('text/plain',card.dataset.scheduleKey);card.classList.add('plannerDragging')}
function plannerScheduleDragOver(ev){if(!plannerDraggingScheduleCard)return;const target=ev.currentTarget;if(!target||target===plannerDraggingScheduleCard||target.dataset.scheduleDate!==plannerDraggingScheduleCard.dataset.scheduleDate)return;ev.preventDefault();ev.dataTransfer.dropEffect='move';target.classList.add('plannerDragOver')}
function plannerScheduleDrop(ev){const target=ev.currentTarget,dragged=plannerDraggingScheduleCard;if(!dragged||!target||dragged===target||target.dataset.scheduleDate!==dragged.dataset.scheduleDate)return;ev.preventDefault();const parent=target.parentElement;if(!parent||parent!==dragged.parentElement)return;const rect=target.getBoundingClientRect(),after=ev.clientY>rect.top+rect.height/2;if(after)parent.insertBefore(dragged,target.nextSibling);else parent.insertBefore(dragged,target);const date=parent.dataset.scheduleDay||dragged.dataset.scheduleDate,order=[...parent.querySelectorAll(':scope > [data-schedule-key]')].map(el=>el.dataset.scheduleKey);const p=db.studyPlan||(db.studyPlan={});if(!p.weeklyCardOrder||typeof p.weeklyCardOrder!=='object')p.weeklyCardOrder={};p.weeklyCardOrder[date]=order;p.updatedAt=Date.now();const ok=save();if(ok&&cloud)syncUp().then(()=>{if(saveState)saveState.textContent='salvo na nuvem'});const msg=document.getElementById('spWeeklyMessage');if(msg)msg.textContent=ok?'Ordem das atividades salva e sincronizada.':'A ordem foi alterada, mas não consegui confirmar o salvamento.';toast(ok?'Ordem das atividades salva.':'Confira o estado do salvamento');}
function plannerScheduleDragEnd(){plannerDraggingScheduleCard=null;document.querySelectorAll('.plannerSlotItem.plannerDragging,.plannerSlotItem.plannerDragOver').forEach(el=>el.classList.remove('plannerDragging','plannerDragOver'))}
function plannerEditStudyTask(id){
 const p=db.studyPlan||{},items=Array.isArray(p.weekSchedule)?p.weekSchedule:[],item=items.find(x=>String(x.id)===String(id));if(!item){toast('Não encontrei essa tarefa no cronograma.');return}
 const title=prompt('Editar tarefa:',item.title||'');if(title===null)return;
 const date=prompt('Data (AAAA-MM-DD):',item.date||'');if(date===null)return;
 const time=prompt('Horário (HH:MM, opcional):',item.startTime||item.time||'');if(time===null)return;
 const minutes=prompt('Duração em minutos:',String(item.minutes||30));if(minutes===null)return;
 const n=Number(minutes);if(!title.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(n)||n<5||n>720){toast('Confira o título, a data e a duração (5–720 min).');return}
 if(time&&!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(time)){toast('Confira o horário no formato HH:MM.');return}
 const taskId=String(item.taskId||item.id);const endMin=time?Number(time.slice(0,2))*60+Number(time.slice(3,5))+n:0;
 for(const part of items){if(String(part.id)===String(id)||String(part.taskId||part.id)===taskId){part.title=title.trim();part.date=date;part.minutes=n;part.startTime=time;part.time=time;part.endTime=time?String(Math.floor(endMin/60)%24).padStart(2,'0')+':'+String(endMin%60).padStart(2,'0'):'';part.updatedAt=Date.now()}}
 const task=(p.weeklyTasks||[]).find(x=>String(x.id)===taskId);if(task){task.title=title.trim();task.date=date;task.minutes=n;task.time=time;task.updatedAt=Date.now()}
 for(const ev of db.agendaEvents||[])if(String(ev.studyTaskId)===taskId){ev.title=title.trim();ev.date=date;ev.time=time;ev.duration=n;ev.updatedAt=Date.now()}
 p.updatedAt=Date.now();const ok=save();const el=document.getElementById('spWeeklySchedule');if(el)el.innerHTML=plannerWeeklyScheduleHtml(p.weekSchedule||[]);if(ok&&cloud)syncUp().then(()=>{if(saveState)saveState.textContent='salvo na nuvem'});toast(ok?'Tarefa atualizada e salva.':'Falha ao salvar; confira o aviso de sincronização.');
}
function toggleWeeklyTask(id,done){const p=db.studyPlan||{};const item=(p.weekSchedule||[]).find(x=>String(x.id)===String(id));if(!item)return;const taskId=String(item.taskId||item.id),stamp=done?new Date().toISOString():null;for(const part of p.weekSchedule||[])if(String(part.id)===String(id)||String(part.taskId||part.id)===taskId){part.done=!!done;part.completedAt=stamp;part.updatedAt=Date.now()}const task=(p.weeklyTasks||[]).find(x=>String(x.id)===taskId);if(task){task.done=!!done;task.completedAt=stamp;task.updatedAt=Date.now()}for(const ev of db.agendaEvents||[])if(String(ev.studyTaskId)===taskId){ev.done=!!done;ev.completedAt=stamp;ev.updatedAt=Date.now()}p.updatedAt=Date.now();const ok=save();const out=document.getElementById('spWeeklySchedule');if(out)out.innerHTML=plannerWeeklyScheduleHtml(p.weekSchedule);if(route==='Dashboard')render();if(ok&&cloud)syncUp();if(!ok)toast('Não foi possível salvar a conclusão.');}
function saveStudyPlan(){
 const name=document.getElementById('spExamName')?.value.trim()||'',date=document.getElementById('spExamDate')?.value||'',minutes=Number(document.getElementById('spMinutes')?.value||60),topics=document.getElementById('spTopics')?.value||'',days=document.getElementById('spDays')?.value||'';
 if(minutes<15||minutes>600){toast('Informe entre 15 e 600 minutos por dia.');return}
 db.studyPlan={...(db.studyPlan||{}),examName:name,examDate:date,minutesPerDay:minutes,topics,days,updatedAt:Date.now()};const ok=save();const m=document.getElementById('spSaveMessage');if(m)m.textContent=ok?'Plano salvo neste aparelho'+(cloud?' e enviado para sincronização.':'.'):'Não foi possível confirmar o salvamento; confira o estado de sincronização.';toast(ok?'Plano salvo ♡':'Confira o estado do salvamento');}
function plannerSessionsHtml(p){
 const sessions=Array.isArray(p?.sessions)?p.sessions:[];
 if(!sessions.length)return '<p class="muted">Seu plano semanal ainda não foi gerado. Configure os assuntos e toque em “Gerar sugestão semanal”.</p>';
 return '<h4>Seu plano semanal</h4><div class="plannerSchedule">'+sessions.map((x,i)=>'<div class="qbox plannerDay '+(x.done?'plannerDone':'')+'"><div class="row" style="justify-content:space-between;align-items:center"><b>'+esc(x.dateLabel||x.date||'Sessão '+(i+1))+'</b><span class="tag">'+Number(x.minutes||p.minutesPerDay||60)+' min</span></div><h3 style="margin:9px 0 5px">'+esc(x.topic)+'</h3><p class="muted">'+esc(x.kind||'Estudo ativo + revisão')+'</p><label class="plannerCheck"><input type="checkbox" '+(x.done?'checked':'')+' onchange="togglePlannerSession('+i+',this.checked)"> Sessão concluída</label></div>').join('')+'</div>';
}
function togglePlannerSession(index,done){
 const p=db.studyPlan||{};if(!Array.isArray(p.sessions)||!p.sessions[index])return;p.sessions[index].done=!!done;p.sessions[index].completedAt=done?new Date().toISOString():null;p.updatedAt=Date.now();const ok=save();const out=document.getElementById('spGenerated');if(out)out.innerHTML=plannerSessionsHtml(p);if(ok&&cloud)syncUp();if(!ok)toast('Confira o estado do salvamento');else toast(done?'Sessão concluída! ♡':'Conclusão desmarcada');
}
function generateStudyPlan(){
 saveStudyPlan();const p=db.studyPlan||{},topics=String(p.topics||'').split(/[,;\\n]/).map(x=>x.trim()).filter(Boolean),days=String(p.days||'Seg, Ter, Qua, Qui, Sex').split(/[,;\\n]/).map(x=>x.trim()).filter(Boolean);
 if(!topics.length){const out=document.getElementById('spGenerated');if(out)out.innerHTML='<p class="muted">Adicione os assuntos que deseja estudar para gerar a sugestão.</p>';return}
 const labels=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'],today=new Date(),items=[];let topicIndex=0;
 for(let i=0;items.length<7&&i<28;i++){const d=new Date(today);d.setDate(today.getDate()+i);const wd=labels[d.getDay()];if(days.length&&!days.some(x=>wd.toLowerCase().startsWith(x.slice(0,3).toLowerCase())))continue;const prior=p.sessions?.find(x=>x.date===d.toISOString().slice(0,10));items.push({date:d.toISOString().slice(0,10),dateLabel:d.toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'2-digit'}),topic:topics[topicIndex%topics.length],minutes:Number(p.minutesPerDay)||60,kind:topicIndex%3===2?'Questões práticas + revisão':'Estudo ativo + revisão espaçada',done:prior?.done||false,completedAt:prior?.completedAt||null});topicIndex++}
 p.sessions=items;p.updatedAt=Date.now();const ok=save();const out=document.getElementById('spGenerated');if(out)out.innerHTML=plannerSessionsHtml(p);const m=document.getElementById('spSaveMessage');if(m)m.textContent=ok?'Plano semanal salvo e sincronizado quando disponível.':'Não foi possível confirmar o salvamento.';toast(ok?'Plano semanal gerado e salvo ♡':'Confira o estado do salvamento');
}
function studyTutorPlaceholder(){return '<div class="panel hero"><div class="row" style="align-items:center;gap:12px"><span style="font-size:32px">🤖</span><div><h2 style="margin:0">Tutor de Estudos com IA</h2><p style="margin:5px 0 0">Conversa de estudo dentro do FlashMed.</p></div></div></div><div class="panel" style="margin-top:14px"><h3>Estamos preparando o tutor com segurança</h3><p>O tutor será conectado por um serviço de backend, sem chaves secretas no código público. Essa tela ainda não envia mensagens para uma IA.</p><p class="muted">Próxima etapa: configurar uma integração segura e depois conectar o tutor ao seu plano de estudos, preservando login e sincronização.</p></div>'}
function dashboardTodayPlanPanel(){
 const d=new Date(),today=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
 const items=(Array.isArray(db.studyPlan?.weekSchedule)?db.studyPlan.weekSchedule:[]).filter(x=>x.date===today);
 const minutes=items.reduce((n,x)=>n+(Number(x.minutes)||0),0),done=items.filter(x=>x.done).length;
 const quote=typeof plannerQuoteOfDay==='function'?plannerQuoteOfDay():'Um passo pequeno também é progresso. ♡';
 const schedule=items.length?items.map(x=>`<label class="plannerCheck" style="display:flex;align-items:flex-start;gap:10px;padding:11px 0;border-bottom:1px solid var(--line)"><input type="checkbox" ${x.done?'checked':''} onchange="toggleWeeklyTask('${x.id}',this.checked)" style="margin-top:4px;flex-shrink:0"><span style="flex:1"><b style="${x.done?'text-decoration:line-through;opacity:.65':''}">${esc(x.title)}</b><span class="muted" style="display:block;margin-top:3px">${Number(x.minutes)||0} min</span></span><span class="tag">${x.done?'Concluída':'Planejada'}</span></label>`).join(''):`<p class="muted">Seu dia ainda está livre de tarefas no cronograma. Se quiser, monte ou ajuste sua semana por aqui.</p><button class="btn ghost" onclick="go('Planejador de Estudos')">Organizar minha semana</button>`;
 return `<div class="cols" style="margin-top:14px;align-items:stretch"><section class="panel" style="background:linear-gradient(135deg,var(--card),var(--rose2))"><div class="muted">♡ UMA LEMBRANÇA PARA HOJE</div><p style="font-size:18px;line-height:1.55;font-family:Georgia,serif;margin:12px 0 4px">${esc(quote)}</p></section><section class="panel"><div class="row" style="justify-content:space-between;align-items:flex-start"><div><h3 style="margin:0">🗓️ Seu cronograma de hoje</h3><p class="muted" style="margin:5px 0 0">${items.length?done+' de '+items.length+' tarefas concluídas':'Um passo de cada vez'}</p></div><span class="tag">${minutes} min</span></div>${items.length?`<div class="bar" style="margin:12px 0 4px"><i style="width:${Math.round(done/Math.max(1,items.length)*100)}%"></i></div>`:''}<div style="margin-top:8px">${schedule}</div>${items.length?`<button class="btn ghost" style="margin-top:12px" onclick="go('Planejador de Estudos')">Ver semana completa</button>`:''}</section></div>`;
}

let fmCalendarMonthOffset=0;
function flashmedStreakStats(){
 const active=new Set();
 const addDate=value=>{const date=String(value||'').slice(0,10);if(/^\d{4}-\d{2}-\d{2}$/.test(date))active.add(date)};
 // A ofensiva do FlashMed representa uso real do site, não apenas estudo acadêmico.
 // Trinta minutos acumulados com a página visível tornam o dia ativo.
 Object.entries(db.siteUsage||{}).forEach(([date,ms])=>{if((Number(ms)||0)>=FM_SITE_STREAK_MINUTES*60000)addDate(date)});
 // Mantém compatibilidade com registros antigos e outras atividades já salvas.
 (db.sessions||[]).forEach(session=>{if((Number(session.minutes)||0)>=1)addDate(session.date)});
 (db.bankAttempts||[]).forEach(attempt=>addDate(attempt.date));
 (db.studyPlan?.weekSchedule||[]).forEach(task=>{if(task.done&&task.completedAt)addDate(task.completedAt)});
 const today=day(),yesterday=new Date(Date.parse(today+'T00:00:00Z')-86400000).toISOString().slice(0,10);
 const lastActive=active.has(today)?today:(active.has(yesterday)?yesterday:null);
 let current=0;
 if(lastActive){let cursor=lastActive;while(active.has(cursor)){current++;cursor=new Date(Date.parse(cursor+'T00:00:00Z')-86400000).toISOString().slice(0,10)}}
 let best=0,run=0,previous=null;
 [...active].sort().forEach(date=>{
  run=previous&&Date.parse(date+'T00:00:00Z')-Date.parse(previous+'T00:00:00Z')===86400000?run+1:1;
  if(run>best)best=run;previous=date;
 });
 return {current,best,studiedToday:active.has(today),activeDays:active.size,activeDates:[...active]};
}

function fmStudyDateKey(date){return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0')}
function fmStudyCalendarShift(delta){fmCalendarMonthOffset=Math.min(0,fmCalendarMonthOffset+delta);render()}

function flashcardInventoryStats(){
 const cards=Array.isArray(db.cards)?db.cards:[];
 const reviewed=c=>Number(c.ok||0)+Number(c.bad||0)>0||(Array.isArray(c.history)&&c.history.length>0);
 const total=cards.length,pending=cards.filter(due).length,studied=cards.filter(reviewed).length,unseen=total-studied,images=cards.filter(c=>!!(c.media||c.image||c.occlusion)).length;
 const subjectRows=(db.subjects||[]).map(subject=>({subject,count:cards.filter(c=>c.subject===subject).length})).filter(x=>x.count);
 const unclassified=cards.filter(c=>!c.subject||(db.subjects||[]).indexOf(c.subject)<0).length;
 return {total,pending,studied,unseen,images,subjectRows,unclassified};
}
function flashcardsInventoryHtml(){
 const st=flashcardInventoryStats();
 return '<section class="fmFlashInventory"><div class="fmFlashInventoryHead"><div><span class="fmEditorialKicker">SEU ACERVO</span><h3>Visão geral dos flashcards</h3><p>Contagem dos cartões cadastrados nesta conta.</p></div><span class="fmFlashTotal"><b>'+st.total+'</b><small>no total</small></span></div><div class="fmFlashInventoryBar" role="img" aria-label="'+st.studied+' estudados de '+st.total+'"><i style="width:'+(st.total?Math.round(st.studied/st.total*100):0)+'%"></i></div><div class="fmFlashInventoryStats"><div><b>'+st.pending+'</b><span>Pendentes para revisão</span></div><div><b>'+st.unseen+'</b><span>Ainda não estudados</span></div><div><b>'+st.studied+'</b><span>Já estudados</span></div><div><b>'+st.images+'</b><span>Com imagem/oclusão</span></div></div><div class="fmFlashSubjectCounts"><b>Por matéria</b>'+st.subjectRows.map(x=>'<span><i>'+esc(x.subject)+'</i><strong>'+x.count+'</strong></span>').join('')+(st.unclassified?'<span class="fmFlashUnclassified"><i>Sem matéria reconhecida</i><strong>'+st.unclassified+'</strong></span>':'')+'</div><p class="fmFlashInventoryNote">“Pendentes” considera a data de revisão de cada cartão. A contagem reflete os dados atualmente carregados; cartões ausentes da conta não podem ser contados aqui.</p></section>';
}
function flashcardsRevisionHub(){return '<section class="fmHubIntro"><span class="fmEditorialKicker">ESTUDAR</span><h2>Flashcards e revisão</h2><p>Consulte seu acervo completo ou revise apenas os cartões pendentes.</p></section>'+flashcardsInventoryHtml()+'<section class="panel" style="margin-top:14px"><div class="row" style="gap:10px;flex-wrap:wrap"><button class="btn" onclick="go(\'Todos os flashcards\')">▤ Ver todos os flashcards</button><button class="btn ghost" onclick="go(\'Revisão\')">↻ Revisões pendentes</button><button class="btn ghost" onclick="go(\'Matérias\')">📚 Organizar por matéria</button></div></section><section class="fmHubSection"><h3>Revisões de hoje</h3>'+review('due')+'</section><section class="fmHubSection"><h3>Suas matérias e flashcards</h3>'+subjects()+'</section>'}
let allFlashcardsSearch='',allFlashcardsSubject='Todas';
function allFlashcardsView(){
 const cards=Array.isArray(db.cards)?db.cards:[];
 const subjects=['Todas',...db.subjects.filter(x=>cards.some(c=>c.subject===x))];
 if(!subjects.includes(allFlashcardsSubject))allFlashcardsSubject='Todas';
 const q=String(allFlashcardsSearch||'').trim().toLocaleLowerCase('pt-BR');
 const filtered=cards.filter(c=>{const subjectOk=allFlashcardsSubject==='Todas'||c.subject===allFlashcardsSubject;const hay=[c.front,c.back,c.tags,c.subject,c.topic].filter(Boolean).join(' ').replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').toLocaleLowerCase('pt-BR');return subjectOk&&(!q||hay.includes(q))});
 const reviewed=c=>Number(c.ok||0)+Number(c.bad||0)>0||(Array.isArray(c.history)&&c.history.length>0);
 return '<section class="fmHubIntro"><span class="fmEditorialKicker">SEU ACERVO COMPLETO</span><h2>Todos os flashcards</h2><p>Cartões disponíveis nesta conta, independentemente de estarem pendentes ou já estudados. O histórico e as imagens são preservados.</p></section>'+
 '<section class="panel" style="margin-top:14px"><div class="row" style="gap:10px;flex-wrap:wrap"><input id="allFlashcardsSearch" class="field" style="flex:1;min-width:220px" placeholder="Buscar pergunta, resposta ou tag…" value="'+esc(allFlashcardsSearch)+'" oninput="allFlashcardsSearch=this.value;renderAllFlashcards()"><select class="field" style="max-width:260px" onchange="allFlashcardsSubject=this.value;renderAllFlashcards()">'+subjects.map(x=>'<option value="'+esc(x)+'" '+(x===allFlashcardsSubject?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select><button class="btn ghost" onclick="go(\'Adicionar flashcard\')">+ Novo flashcard</button></div><div class="row" style="margin-top:10px;justify-content:space-between"><span class="pill">'+filtered.length+' de '+cards.length+' cartões</span><span class="muted">'+cards.filter(reviewed).length+' já estudados · '+cards.filter(due).length+' pendentes</span></div></section>'+
 '<section class="panel" style="margin-top:14px"><h3>Acervo</h3>'+(filtered.length?filtered.map(c=>'<article class="qbox"><div class="row" style="justify-content:space-between;align-items:flex-start"><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><span class="tag">'+esc(c.subject||'Sem matéria')+(c.tags?' · '+esc(c.tags):'')+'</span><select class="field" aria-label="Reclassificar matéria" style="max-width:210px;padding:6px 9px" onchange="reassignFlashcardSubject('+JSON.stringify(c.id)+',this.value)"><option value="">Mover para…</option>'+db.subjects.map(sub=>'<option value="'+esc(sub)+'" '+(sub===c.subject?'selected':'')+'>'+esc(sub)+'</option>').join('')+'</select></div><div class="row"><button class="btn ghost mini" onclick="editCard('+JSON.stringify(c.id)+')">✏️ Editar</button><button class="btn ghost mini" onclick="deleteCard('+JSON.stringify(c.id)+')">🗑️</button></div></div><div class="rich" style="margin-top:8px"><b>Frente:</b> '+cardFrontHtml(c)+'</div><details style="margin-top:8px"><summary><b>Ver resposta</b></summary><div class="rich" style="margin-top:8px">'+cardBackHtml(c)+'</div>'+(c.media?media(c.media):'')+'</details><div class="muted" style="margin-top:8px">Próxima revisão: '+esc(c.due||'hoje')+' · Acertos: '+(c.ok||0)+' · Erros: '+(c.bad||0)+(c.occlusion?' · Cartão com imagem/oclusão':'')+'</div></article>').join(''):'<p class="muted">Nenhum cartão encontrado com esses filtros.</p>')+'</section>';
}
function reassignFlashcardSubject(id,nextSubject){
 const c=(db.cards||[]).find(x=>String(x.id)===String(id));
 if(!c)return;
 if(!nextSubject||!(db.subjects||[]).includes(nextSubject)){toast('Escolha uma matéria válida');return}
 c.subject=nextSubject;
 save();
 toast('Matéria do flashcard atualizada ♡');
 renderAllFlashcards();
}
function renderAllFlashcards(){const node=document.getElementById('view');if(!node||route!=='Todos os flashcards')return;const active=document.activeElement,searching=!!(active&&active.id==='allFlashcardsSearch'),pos=searching?active.selectionStart:null;node.innerHTML=allFlashcardsView();if(searching){const input=document.getElementById('allFlashcardsSearch');if(input){input.focus();try{input.setSelectionRange(pos,pos)}catch(e){}}}}
function studyAgendaHub(){return '<section class="fmHubIntro"><span class="fmEditorialKicker">PLANEJAMENTO</span><h2>Seu plano e sua agenda</h2><p>Organize as tarefas de estudo e os compromissos pessoais em um só lugar.</p></section><section class="fmHubSection"><h3>Planejamento de estudos</h3>'+studyPlannerView()+'</section><section class="fmHubSection"><h3>Agenda geral</h3>'+agendaGeneralView()+'</section>'}

function fmDashboardWeekHtml(){
 const today=new Date(),start=new Date(today);start.setHours(12,0,0,0);start.setDate(today.getDate()-((today.getDay()+6)%7)+plannerDefaultWeekOffset(today)*7);
 const schedule=Array.isArray(db.studyPlan?.weekSchedule)?db.studyPlan.weekSchedule:[],events=plannerDeduplicateEvents(agendaEvents().filter(e=>e&&e.date&&!e.studyTaskId)),days=['SEG','TER','QUA','QUI','SEX','SÁB','DOM'];let cells='';
 for(let i=0;i<7;i++){
  const d=new Date(start);d.setDate(start.getDate()+i);const key=agendaDateKey(d),isToday=key===agendaDateKey(today);
  const tasks=schedule.filter(x=>x.date===key).sort((x,y)=>(x.startTime||'99:99').localeCompare(y.startTime||'99:99')),ev=events.filter(x=>x.date===key).sort((x,y)=>(x.time||'99:99').localeCompare(y.time||'99:99'));
  const total=tasks.length+ev.length;
  cells+='<div class="fmWeekDay'+(isToday?' isToday':'')+'"><div class="fmWeekDayHead"><span>'+days[i]+'</span><b>'+d.getDate()+'</b></div><div class="fmWeekDayItems">'+tasks.map(t=>'<span class="fmWeekPill study'+(t.done?' fmWeekPillDone':'')+'" style="border-left:3px solid '+(/^#[0-9a-f]{6}$/i.test(t.color||'')?t.color:'#a58abf')+'"><span class="fmWeekPillTitle">'+esc(t.startTime?t.startTime+' ':'')+esc(t.title)+'</span></span>').join('')+ev.map(e=>'<span class="fmWeekPill '+(/prova|avalia|semin.rio|exame/i.test(e.title||'')?'academic':'')+(e.done?' fmWeekPillDone':'')+'"><span class="fmWeekPillTitle">'+esc(e.time?e.time+' ':'')+esc(e.title)+'</span></span>').join('')+(!total?'<span class="fmWeekEmpty">Livre</span>':'')+'</div></div>';
 }
 return '<section class="panel fmWeekPanel"><div class="fmWeekTop"><div><span class="fmEditorialKicker">VISÃO DA SEMANA</span><h3>Calendário da semana</h3><p class="muted">Todas as atividades da semana, com horários quando informados.</p></div><button class="btn ghost" onclick="go(\'Planejador de Estudos\')">Editar semana ↗</button></div><div class="fmWeekGrid">'+cells+'</div></section>';
}
